export interface ConnectorConfig {
  /** Stripe webhook signing secret for signature verification (optional but recommended). */
  stripeWebhookSecret?: string;
  /** Mailchimp API key (format: 'key-us1', 'key-us2', etc.). */
  mailchimpApiKey: string;
  /** Mailchimp audience (list) ID. */
  mailchimpAudienceId: string;
  /** Mailchimp datacenter prefix (e.g., 'us1', 'us2'). Derived from API key suffix if not provided. */
  mailchimpDatacenter?: string;
  /** Fallback tag to use when Stripe plan ID cannot be determined from the webhook payload. */
  fallbackPlanTag?: string;
  /** Injected fetch implementation for testing. */
  fetch?: typeof fetch;
}

export interface StripeWebhookPayload {
  id: string;
  object: 'checkout.session';
  mode: 'subscription' | 'payment' | 'setup';
  payment_status: 'paid' | 'unpaid' | 'no_payment_required';
  customer: string | StripeCustomer;
  customer_details: {
    email: string;
    name?: string;
  };
  subscription: string | StripeSubscription;
  success_url?: string;
  [key: string]: unknown;
}

export interface StripeCustomer {
  id: string;
  email?: string;
  subscriptions?: {
    data: Array<{
      plan: {
        id: string;
      };
    }>;
  };
  [key: string]: unknown;
}

export interface StripeSubscription {
  id: string;
  plan?: {
    id: string;
  };
  [key: string]: unknown;
}

export interface MailchimpMemberPayload {
  email_address: string;
  status: 'subscribed' | 'unsubscribed' | 'cleaned' | 'pending' | 'transactional';
  tags?: string[];
  merge_fields?: Record<string, string>;
}

export interface MailchimpMemberResponse {
  id: string;
  email_address: string;
  status: string;
  tags: string[];
  merge_fields: Record<string, string>;
  [key: string]: unknown;
}

export interface HandleResult {
  mailchimpMemberId: string;
  email: string;
  planTag: string;
}

function extractPlanId(payload: StripeWebhookPayload): string | null {
  // Try expanded customer.subscriptions.data[0].plan.id
  if (typeof payload.customer === 'object' && payload.customer.subscriptions?.data?.[0]?.plan?.id) {
    return payload.customer.subscriptions.data[0].plan.id;
  }
  // Try expanded subscription.plan.id
  if (typeof payload.subscription === 'object' && payload.subscription.plan?.id) {
    return payload.subscription.plan.id;
  }
  // Try customer.email as last resort (not a plan ID but indicates customer exists)
  return null;
}

function getDatacenter(apiKey: string, configured?: string): string {
  if (configured) return configured;
  const match = apiKey.match(/-([a-z0-9]+)$/i);
  return match?.[1] ?? 'us1';
}

function buildBasicAuthHeader(apiKey: string): string {
  const credentials = `anystring:${apiKey}`;
  const encoded = btoa(credentials);
  return `Basic ${encoded}`;
}

function btoa(str: string): string {
  if (typeof btoa === 'function' && typeof globalThis !== 'undefined' && 'btoa' in globalThis) {
    return (globalThis as { btoa: (s: string) => string }).btoa(str);
  }
  // Node.js / modern browsers
  return Buffer.from(str, 'binary').toString('base64');
}

export async function handle(
  payload: StripeWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch;

  // Validate required fields
  if (!payload.id) throw new Error('Missing required field: id');
  if (payload.object !== 'checkout.session') throw new Error('Invalid object type: expected checkout.session');
  if (payload.mode !== 'subscription') throw new Error(`Unsupported mode: ${payload.mode}. Only subscription mode is handled.`);
  if (payload.payment_status !== 'paid') throw new Error(`Payment not completed: ${payload.payment_status}`);
  if (!payload.customer_details?.email) throw new Error('Missing required field: customer_details.email');

  const email = payload.customer_details.email;
  const planId = extractPlanId(payload);
  const planTag = planId ?? config.fallbackPlanTag ?? 'stripe_plan_unknown';

  const datacenter = getDatacenter(config.mailchimpApiKey, config.mailchimpDatacenter);
  const url = `https://${datacenter}.api.mailchimp.com/3.0/lists/${config.mailchimpAudienceId}/members`;

  const memberPayload: MailchimpMemberPayload = {
    email_address: email,
    status: 'subscribed',
    tags: [planTag],
    merge_fields: {
      INTERESTS: planTag,
    },
  };

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': buildBasicAuthHeader(config.mailchimpApiKey),
      'Content-Type': 'application/json',
      'Accept': 'application/json',
    },
    body: JSON.stringify(memberPayload),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    throw new Error(`Mailchimp API error (${response.status} ${response.statusText}) at POST ${url}: ${errorText}`);
  }

  const member = (await response.json()) as MailchimpMemberResponse;

  return {
    mailchimpMemberId: member.id,
    email: member.email_address,
    planTag,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, StripeWebhookPayload } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpAudienceId: 'audience_123',
      mailchimpDatacenter: 'us1',
      fallbackPlanTag: 'price_fallback',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.mailchimpMemberId).toBe('abc123');
    expect(result.email).toBe('customer@example.com');
    expect(result.planTag).toBe('price_fallback');
  });
});

describe('handle', () => {
  it('successfully adds subscriber with plan tag from expanded customer', async () => {
    const payload: StripeWebhookPayload = {
      ...SOURCE_EXAMPLE,
      customer: {
        id: 'cus_1234567890',
        subscriptions: {
          data: [{ plan: { id: 'price_G0FvDp6vZvdwRZ' } }],
        },
      },
      subscription: {
        id: 'sub_1234567890',
        plan: { id: 'price_G0FvDp6vZvdwRZ' },
      },
    };
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST');
      expect(req.url).toBe('https://us1.api.mailchimp.com/3.0/lists/audience_123/members');
      expect(req.headers.get('authorization')).toBe('Basic YW55c3RyaW5nOnRlc3Qta2V5LXVzMQ==');
      expect(req.json).toEqual({
        email_address: 'customer@example.com',
        status: 'subscribed',
        tags: ['price_G0FvDp6vZvdwRZ'],
        merge_fields: { INTERESTS: 'price_G0FvDp6vZvdwRZ' },
      });
      return jsonResponse(TARGET_ENDPOINTS[0].response);
    });
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpAudienceId: 'audience_123',
      mailchimpDatacenter: 'us1',
      fetch,
    };
    const result = await handle(payload, config);
    expect(result.mailchimpMemberId).toBe('abc123');
    expect(result.planTag).toBe('price_G0FvDp6vZvdwRZ');
    expect(calls.length).toBe(1);
  });

  it('uses fallback tag when plan ID not in payload', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({
        email_address: 'customer@example.com',
        status: 'subscribed',
        tags: ['fallback_plan'],
        merge_fields: { INTERESTS: 'fallback_plan' },
      });
      return jsonResponse(TARGET_ENDPOINTS[0].response);
    });
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpAudienceId: 'audience_123',
      mailchimpDatacenter: 'us1',
      fallbackPlanTag: 'fallback_plan',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config);
    expect(result.planTag).toBe('fallback_plan');
    expect(calls.length).toBe(1);
  });

  it('throws on missing customer_details.email', async () => {
    const payload = { ...SOURCE_EXAMPLE, customer_details: {} };
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpAudienceId: 'audience_123',
      fetch,
    };
    await expect(handle(payload as unknown as StripeWebhookPayload, config)).rejects.toThrow(
      'Missing required field: customer_details.email'
    );
  });

  it('throws on non-subscription mode', async () => {
    const payload = { ...SOURCE_EXAMPLE, mode: 'payment' as const };
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpAudienceId: 'audience_123',
      fetch,
    };
    await expect(handle(payload, config)).rejects.toThrow('Unsupported mode: payment');
  });

  it('throws on unpaid payment_status', async () => {
    const payload = { ...SOURCE_EXAMPLE, payment_status: 'unpaid' as const };
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpAudienceId: 'audience_123',
      fetch,
    };
    await expect(handle(payload, config)).rejects.toThrow('Payment not completed: unpaid');
  });

  it('throws on Mailchimp API error with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ detail: 'Invalid email' }, 400));
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpAudienceId: 'audience_123',
      mailchimpDatacenter: 'us1',
      fetch,
    };
    await expect(handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config)).rejects.toThrow(
      'Mailchimp API error (400 Bad Request) at POST https://us1.api.mailchimp.com/3.0/lists/audience_123/members'
    );
    expect(calls.length).toBe(1);
  });

  it('derives datacenter from API key when not configured', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.url).toBe('https://us2.api.mailchimp.com/3.0/lists/audience_123/members');
      return jsonResponse(TARGET_ENDPOINTS[0].response);
    });
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us2',
      mailchimpAudienceId: 'audience_123',
      fetch,
    };
    await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config);
    expect(calls.length).toBe(1);
  });

  it('uses configured datacenter over API key suffix', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.url).toBe('https://eu1.api.mailchimp.com/3.0/lists/audience_123/members');
      return jsonResponse(TARGET_ENDPOINTS[0].response);
    });
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us2',
      mailchimpAudienceId: 'audience_123',
      mailchimpDatacenter: 'eu1',
      fetch,
    };
    await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config);
    expect(calls.length).toBe(1);
  });

  it('sends correct basic auth header', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const auth = req.headers.get('authorization');
      expect(auth).toBe('Basic YW55c3RyaW5nOnRlc3Qta2V5LXVzMQ=='); // anystring:test-key-us1
      return jsonResponse(TARGET_ENDPOINTS[0].response);
    });
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key-us1',
      mailchimpAudienceId: 'audience_123',
      fetch,
    };
    await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config);
    expect(calls.length).toBe(1);
  });
});

# Stripe to Mailchimp Connector

Adds a customer to a Mailchimp audience with their Stripe plan as a tag when a checkout session completes successfully.

## What it does

Listens for Stripe `checkout.session.completed` webhooks (subscription mode, paid status). Extracts the customer email and plan ID, then creates or updates a Mailchimp audience member with:
- `email_address` from Stripe `customer_details.email`
- `status: "subscribed"`
- `tags` containing the Stripe plan ID (e.g., `price_G0FvDp6vZvdwRZ`)
- `merge_fields.INTERESTS` set to the same plan ID for interest group targeting

## Configuration

| Config Property | Environment Variable | Required | Description |
|-----------------|---------------------|----------|-------------|
| `stripeWebhookSecret` | `STRIPE_WEBHOOK_SECRET` | No | Stripe webhook signing secret for signature verification. Not used by this connector but documented for completeness. |
| `mailchimpApiKey` | `MAILCHIMP_API_KEY` | **Yes** | Mailchimp API key (format: `key-us1`, `key-us2`, etc.). Used for Basic auth. |
| `mailchimpAudienceId` | `MAILCHIMP_AUDIENCE_ID` | **Yes** | Mailchimp audience (list) ID. |
| `mailchimpDatacenter` | `MAILCHIMP_DATACENTER` | No | Datacenter prefix (e.g., `us1`, `us2`, `eu1`). Defaults to suffix of `mailchimpApiKey`. |
| `fallbackPlanTag` | `FALLBACK_PLAN_TAG` | No | Tag to use when plan ID cannot be extracted from webhook payload. Default: `stripe_plan_unknown`. |

## Usage Example

```typescript
import { handle, ConnectorConfig } from './connector';

const config: ConnectorConfig = {
  mailchimpApiKey: process.env.MAILCHIMP_API_KEY!,
  mailchimpAudienceId: process.env.MAILCHIMP_AUDIENCE_ID!,
  mailchimpDatacenter: process.env.MAILCHIMP_DATACENTER,
  fallbackPlanTag: process.env.FALLBACK_PLAN_TAG,
};

// In your webhook handler (e.g., Express, Fastify, Cloudflare Workers):
app.post('/stripe-webhook', async (req, res) => {
  try {
    const result = await handle(req.body, config);
    res.json({ success: true, memberId: result.mailchimpMemberId });
  } catch (err) {
    console.error(err);
    res.status(400).json({ error: err.message });
  }
});
```

## Assumptions

1. The Stripe webhook payload includes a customer object with email and active subscription data. The connector handles both expanded (`customer.subscriptions.data[0].plan.id`) and unexpanded payloads. If the plan ID is not present, `fallbackPlanTag` is used.
2. The Mailchimp audience is pre-configured to accept tags matching Stripe plan IDs (e.g., `price_...`). Tags must exist in the audience or Mailchimp will ignore them.
3. The user has already set up the Mailchimp API key and audience ID in the connector configuration.
4. The Mailchimp interest group `INTERESTS` exists with the same ID as the plan tag. If not, Mailchimp may ignore the merge field.
5. Stripe webhook signature verification is handled upstream (e.g., by the platform or middleware). The `stripeWebhookSecret` config is documented but not used by this connector.
6. If the subscriber already exists in Mailchimp, the API returns a 400 error. This connector does not implement upsert (PATCH) logic; handle idempotency upstream or extend the connector as needed.

