function extractPlanId(payload: StripeWebhookPayload): string | null {
  // Try expanded customer.subscriptions.data[0].plan.id
  if (typeof payload.customer === 'object' && payload.customer.subscriptions?.data?.[0]?.plan?.id) {
    return payload.customer.subscriptions.data[0].plan.id;
  }
  // Try expanded subscription.plan.id
  if (typeof payload.subscription === 'object' && payload.subscription.plan?.id) {
    return payload.subscription.plan.id;
  }
  // Try customer.email as last resort (not a plan ID but indicates customer exists)
  return null;
}

function getDatacenter(apiKey: string, configured?: string): string {
  if (configured) return configured;
  const match = apiKey.match(/-([a-z0-9]+)$/i);
  return match?.[1] ?? 'us1';
