function btoa(str: string): string {
  if (typeof btoa === 'function' && typeof globalThis !== 'undefined' && 'btoa' in globalThis) {
    return (globalThis as { btoa: (s: string) => string }).btoa(str);
  }
  // Node.js / modern browsers
  return Buffer.from(str, 'binary').toString('base64');
}

export async function handle(
  payload: StripeWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch;

  // Validate required fields
  if (!payload.id) throw new Error('Missing required field: id');
  if (payload.object !== 'checkout.session') throw new Error('Invalid object type: expected checkout.session');
  if (payload.mode !== 'subscription') throw new Error(`Unsupported mode: ${payload.mode}. Only subscription mode is handled.`);
  if (payload.payment_status !== 'paid') throw new Error(`Payment not completed: ${payload.payment_status}`);
  if (!payload.customer_details?.email) throw new Error('Missing required field: customer_details.email');

  const email = payload.customer_details.email;
  const planId = extractPlanId(payload);
  const planTag = planId ?? config.fallbackPlanTag ?? 'stripe_plan_unknown';

  const datacenter = getDatacenter(config.mailchimpApiKey, config.mailchimpDatacenter);
  const url = `https://${datacenter}.api.mailchimp.com/3.0/lists/${config.mailchimpAudienceId}/members`;

  const memberPayload: MailchimpMemberPayload = {
    email_address: email,
    status: 'subscribed',
    tags: [planTag],
    merge_fields: {
      INTERESTS: planTag,
    },
  };

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': buildBasicAuthHeader(config.mailchimpApiKey),
      'Content-Type': 'application/json',
      'Accept': 'application/json',
    },
    body: JSON.stringify(memberPayload),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    throw new Error(`Mailchimp API error (${response.status} ${response.statusText}) at POST ${url}: ${errorText}`);
  }

  const member = (await response.json()) as MailchimpMemberResponse;

  return {
    mailchimpMemberId: member.id,
    email: member.email_address,
    planTag,
  };
}

